cssCode:
.confetti {
  position: absolute; width: 10px; height: 10px;
  background: #fff; opacity: 0; pointer-events: none;
  animation: explode 1s ease-out forwards;
}
@keyframes explode {
  0% { transform: translate(0, 0) scale(1) rotate(0deg); opacity: 1; }
  100% { transform: translate(var(--tx), var(--ty)) scale(0) rotate(720deg); opacity: 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;cursor:pointer;';
c.title = "Click/Touch to Blast!";

c.addEventListener('pointerdown', (e) => {
  const rect = c.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  const colors = ['#00ffcc', '#ff007f', '#ffff00', '#007fff'];

  for(let i=0; i<30; i++) {
    const p = document.createElement('div');
    p.className = 'confetti';
    p.style.left = `${x}px`;
    p.style.top = `${y}px`;
    p.style.background = colors[Math.floor(Math.random() * colors.length)];

    // રેન્ડમ દિશા
    const angle = Math.random() * Math.PI * 2;
    const velocity = 50 + Math.random() * 100;
    p.style.setProperty('--tx', `${Math.cos(angle) * velocity}px`);
    p.style.setProperty('--ty', `${Math.sin(angle) * velocity}px`);

    c.appendChild(p);
    setTimeout(() => p.remove(), 1000);
  }
});
